 17	import io.javalin.Javalin;
 18	import io.javalin.json.JavalinJackson;
 19	
 20	public class App {
 21	    public static void main(String[] args) {
 22	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 23	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 24	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 25	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 26	
 27	        DatabaseManager dbManager = new DatabaseManager(dbUrl, dbUser, dbPassword);
 28	        dbManager.initialize();
 29	
 30	        RoomRepository roomRepository = new RoomRepository(dbManager);
 31	        ReservationRepository reservationRepository = new ReservationRepository(dbManager);
 32	        MessageRepository messageRepository = new MessageRepository(dbManager);
 33	
 34	        PricingService pricingService = new PricingService();
 35	        ReservationService reservationService = new ReservationService(
 36	            reservationRepository, roomRepository, messageRepository, pricingService);
 37	        ReportService reportService = new ReportService(
 38	            reservationRepository, roomRepository, pricingService);
 39	
 40	        RoomHandler roomHandler = new RoomHandler(roomRepository);
 41	        ReservationHandler reservationHandler = new ReservationHandler(
 42	            reservationService, reservationRepository, roomRepository);
 43	        MessageHandler messageHandler = new MessageHandler(messageRepository);
 44	        ReportHandler reportHandler = new ReportHandler(reportService);
 45	
 46	        ObjectMapper objectMapper = new ObjectMapper();
 47	        objectMapper.registerModule(new JavaTimeModule());
 48	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 49	
 50	        Javalin app = Javalin.create(config -> {
 51	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 52	        }).start(port);
 53	
 54	        app.get("/rooms", roomHandler::getAllRooms);
 55	
 56	        app.post("/reservations", reservationHandler::createReservation);
 57	        app.get("/reservations/{id}", reservationHandler::getReservation);
 58	        app.post("/reservations/{id}/confirmation", reservationHandler::confirmReservation);
 59	        app.post("/reservations/{id}/cancellation", reservationHandler::cancelReservation);
 60	        app.post("/reservations/{id}/check-in", reservationHandler::checkIn);
 61	        app.post("/reservations/{id}/check-out", reservationHandler::checkOut);
 62	        app.get("/reservations/{id}/document", reservationHandler::getDocument);
 63	
 64	        app.get("/messages", messageHandler::getAllMessages);
 65	
 66	        app.get("/reports/occupancy", reportHandler::getOccupancyReport);
 67	        app.get("/reports/revenue", reportHandler::getRevenueReport);
 68	        app.get("/reports/tourism-tax", reportHandler::getTourismTaxReport);
 69	        app.get("/reports/rate-plans", reportHandler::getRatePlansReport);
 70	
 71	        System.out.println("Pousada Maré Alta reservation system running on port " + port);
 72	    }
 73	}
