329	    public ReservationHandler(ReservationService reservationService,
330	                            ReservationRepository reservationRepository,
331	                            RoomRepository roomRepository) {
332	        this.reservationService = reservationService;
333	        this.reservationRepository = reservationRepository;
334	        this.roomRepository = roomRepository;
335	    }
