337	    public void createReservation(Context ctx) {
338	        try {
339	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
340	
341	            if (request.getRoomNumber() == null || request.getGuestName() == null ||
342	                request.getGuestEmail() == null || request.getGuestCpf() == null ||
343	                request.getCheckIn() == null || request.getCheckOut() == null ||
344	                request.getGuests() == null || request.getRatePlan() == null) {
345	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
346	                return;
347	            }
348	
349	            LocalDate checkIn;
350	            LocalDate checkOut;
351	            try {
352	                checkIn = LocalDate.parse(request.getCheckIn());
353	                checkOut = LocalDate.parse(request.getCheckOut());
354	            } catch (DateTimeParseException e) {
355	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
356	                return;
357	            }
358	
359	            RatePlan ratePlan;
360	            try {
361	                ratePlan = RatePlan.valueOf(request.getRatePlan());
362	            } catch (IllegalArgumentException e) {
363	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
364	                return;
365	            }
366	
367	            Reservation reservation = reservationService.createReservation(
368	                request.getRoomNumber(),
369	                request.getGuestName(),
370	                request.getGuestEmail(),
371	                request.getGuestCpf(),
372	                checkIn,
373	                checkOut,
374	                request.getGuests(),
375	                ratePlan
376	            );
377	
378	            ctx.status(201).json(toResponseMap(reservation));
379	
380	        } catch (ReservationService.RoomNotFoundException e) {
381	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
382	        } catch (ReservationService.InvalidRequestException e) {
383	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
384	        } catch (ReservationService.CapacityExceededException e) {
385	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
386	        } catch (ReservationService.RoomUnavailableException e) {
387	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
388	        } catch (Exception e) {
389	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request"));
390	        }
391	    }
