393	    public void getReservation(Context ctx) {
394	        try {
395	            Long id = Long.parseLong(ctx.pathParam("id"));
396	            Reservation reservation = reservationRepository.findById(id)
397	                .orElseThrow(() -> new ReservationService.ReservationNotFoundException());
398	
399	            ctx.json(toResponseMap(reservation));
400	
401	        } catch (NumberFormatException e) {
402	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
403	        } catch (ReservationService.ReservationNotFoundException e) {
404	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
405	        }
406	    }
