 81	public class DatabaseManager {
 82	    private final String url;
 83	    private final String user;
 84	    private final String password;
 85	
 86	    public DatabaseManager(String url, String user, String password) {
 87	        this.url = url;
 88	        this.user = user;
 89	        this.password = password;
 90	    }
 91	
 92	    public Connection getConnection() throws SQLException {
 93	        return DriverManager.getConnection(url, user, password);
 94	    }
 95	
 96	    public void initialize() {
 97	        try (Connection conn = getConnection();
 98	             Statement stmt = conn.createStatement()) {
 99	
100	            stmt.execute("""
101	                CREATE TABLE IF NOT EXISTS rooms (
102	                    number VARCHAR(10) PRIMARY KEY,
103	                    type VARCHAR(20) NOT NULL
104	                )
105	                """);
106	
107	            stmt.execute("""
108	                CREATE TABLE IF NOT EXISTS reservations (
109	                    id SERIAL PRIMARY KEY,
110	                    room_number VARCHAR(10) NOT NULL,
111	                    guest_name VARCHAR(255) NOT NULL,
112	                    guest_email VARCHAR(255) NOT NULL,
113	                    guest_cpf VARCHAR(14) NOT NULL,
114	                    check_in DATE NOT NULL,
115	                    check_out DATE NOT NULL,
116	                    guests INTEGER NOT NULL,
117	                    rate_plan VARCHAR(20) NOT NULL,
118	                    nights INTEGER NOT NULL,
119	                    subtotal DECIMAL(10, 2) NOT NULL,
120	                    discount DECIMAL(10, 2) NOT NULL,
121	                    total DECIMAL(10, 2) NOT NULL,
122	                    status VARCHAR(20) NOT NULL,
123	                    amount_paid DECIMAL(10, 2) NOT NULL,
124	                    refund DECIMAL(10, 2),
125	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
126	                )
127	                """);
128	
129	            stmt.execute("""
130	                CREATE TABLE IF NOT EXISTS messages (
131	                    id SERIAL PRIMARY KEY,
132	                    channel VARCHAR(20) NOT NULL,
133	                    recipient VARCHAR(255) NOT NULL,
134	                    subject VARCHAR(500) NOT NULL,
135	                    body TEXT NOT NULL
136	                )
137	                """);
138	
139	            initializeRooms(conn);
140	
141	        } catch (SQLException e) {
142	            throw new RuntimeException("Failed to initialize database", e);
143	        }
144	    }
145	
146	    private void initializeRooms(Connection conn) throws SQLException {
147	        try (Statement stmt = conn.createStatement()) {
148	            stmt.execute("SELECT COUNT(*) FROM rooms");
149	            var rs = stmt.getResultSet();
150	            rs.next();
151	            if (rs.getInt(1) == 0) {
152	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('101', 'STANDARD')");
153	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('102', 'STANDARD')");
154	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('201', 'DELUXE')");
155	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('202', 'DELUXE')");
156	                stmt.execute("INSERT INTO rooms (number, type) VALUES ('301', 'SUITE')");
157	            }
158	        }
159	    }
160	}
