  3	import java.math.BigDecimal;
  4	import java.math.RoundingMode;
  5	import java.time.LocalDate;
  6	import java.time.Month;
  7	
  8	public class PricingService {
  9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 10	
 11	    public BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate date) {
 12	        if (isHighSeason(date)) {
 13	            return roundBankers(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
 14	        }
 15	        return baseRate;
 16	    }
 17	
 18	    public boolean isHighSeason(LocalDate date) {
 19	        int month = date.getMonthValue();
 20	        int day = date.getDayOfMonth();
 21	
 22	        if (month == Month.DECEMBER.getValue() && day >= 15) {
 23	            return true;
 24	        }
 25	
 26	        if (month == Month.JANUARY.getValue() || month == Month.FEBRUARY.getValue()) {
 27	            return true;
 28	        }
 29	
 30	        if (month == Month.JULY.getValue()) {
 31	            return true;
 32	        }
 33	
 34	        return false;
 35	    }
 36	
 37	    public BigDecimal roundBankers(BigDecimal value) {
 38	        return value.setScale(2, RoundingMode.HALF_EVEN);
 39	    }
 40	}
