245	public class ReservationService {
246	    private final ReservationRepository reservationRepository;
247	    private final RoomRepository roomRepository;
248	    private final MessageRepository messageRepository;
249	    private final PricingService pricingService;
250	
251	    public ReservationService(ReservationRepository reservationRepository,
252	                            RoomRepository roomRepository,
253	                            MessageRepository messageRepository,
254	                            PricingService pricingService) {
255	        this.reservationRepository = reservationRepository;
256	        this.roomRepository = roomRepository;
257	        this.messageRepository = messageRepository;
258	        this.pricingService = pricingService;
259	    }
260	
261	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
262	                                       String guestCpf, LocalDate checkIn, LocalDate checkOut,
263	                                       int guests, RatePlan ratePlan) {
264	        Room room = roomRepository.findByNumber(roomNumber)
265	            .orElseThrow(() -> new RoomNotFoundException());
266	
267	        if (guests < 1) {
268	            throw new InvalidRequestException("At least one guest is required");
269	        }
270	
271	        if (guests > room.getCapacity()) {
272	            throw new CapacityExceededException();
273	        }
274	
275	        if (!checkOut.isAfter(checkIn)) {
276	            throw new InvalidRequestException("Check-out must be after check-in");
277	        }
278	
279	        var conflicts = reservationRepository.findConflicting(roomNumber, checkIn, checkOut, null);
280	        if (!conflicts.isEmpty()) {
281	            throw new RoomUnavailableException();
282	        }
283	
284	        Reservation reservation = new Reservation();
285	        reservation.setRoomNumber(roomNumber);
286	        reservation.setGuestName(guestName);
287	        reservation.setGuestEmail(guestEmail);
288	        reservation.setGuestCpf(guestCpf);
289	        reservation.setCheckIn(checkIn);
290	        reservation.setCheckOut(checkOut);
291	        reservation.setGuests(guests);
292	        reservation.setRatePlan(ratePlan);
293	
294	        calculatePricing(reservation, room);
295	
296	        return reservationRepository.save(reservation);
297	    }
298	
299	    private void calculatePricing(Reservation reservation, Room room) {
300	        int nights = (int) ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
301	        reservation.setNights(nights);
302	
303	        BigDecimal subtotal = BigDecimal.ZERO;
304	        LocalDate currentDate = reservation.getCheckIn();
305	
306	        for (int i = 0; i < nights; i++) {
307	            BigDecimal nightPrice = pricingService.calculateNightPrice(room.getNightlyRate(), currentDate);
308	            subtotal = subtotal.add(nightPrice);
309	            currentDate = currentDate.plusDays(1);
310	        }
311	
312	        subtotal = pricingService.roundBankers(subtotal);
313	        reservation.setSubtotal(subtotal);
314	
315	        BigDecimal discount = BigDecimal.ZERO;
316	        if (reservation.getRatePlan() == RatePlan.NON_REFUNDABLE) {
317	            discount = pricingService.roundBankers(subtotal.multiply(reservation.getRatePlan().getDiscountRate()));
318	        }
319	        reservation.setDiscount(discount);
320	
321	        BigDecimal total = pricingService.roundBankers(subtotal.subtract(discount));
322	        reservation.setTotal(total);
323	    }
