325	    public Reservation confirmReservation(Long id) {
326	        Reservation reservation = reservationRepository.findById(id)
327	            .orElseThrow(() -> new ReservationNotFoundException());
328	
329	        if (reservation.getStatus() != ReservationStatus.PENDING) {
330	            throw new OperationNotAllowedException();
331	        }
332	
333	        reservation.setStatus(ReservationStatus.CONFIRMED);
334	        reservation.setAmountPaid(reservation.getTotal());
335	        reservationRepository.save(reservation);
336	
337	        sendConfirmationEmail(reservation);
338	
339	        return reservation;
340	    }
