342	    private void sendConfirmationEmail(Reservation reservation) {
343	        String receipt = generateReceipt(reservation);
344	        String subject = "Reserva confirmada - Pousada Maré Alta";
345	        String body = String.format("""
346	            Olá, %s!
347	
348	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
349	
350	            %s
351	
352	            A entrada é a partir das 14h, e a saída, até as 12h.
353	            Até breve!""", reservation.getGuestName(), receipt);
354	
355	        Message message = new Message(MessageChannel.EMAIL, reservation.getGuestEmail(), subject, body);
356	        messageRepository.save(message);
357	    }
