359	    public Reservation cancelReservation(Long id) {
360	        Reservation reservation = reservationRepository.findById(id)
361	            .orElseThrow(() -> new ReservationNotFoundException());
362	
363	        if (reservation.getStatus() != ReservationStatus.PENDING &&
364	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
365	            throw new OperationNotAllowedException();
366	        }
367	
368	        reservation.setStatus(ReservationStatus.CANCELLED);
369	
370	        BigDecimal refundAmount = BigDecimal.ZERO;
371	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
372	            refundAmount = reservation.getAmountPaid();
373	        }
374	        reservation.setRefund(refundAmount);
375	
376	        return reservationRepository.save(reservation);
377	    }
378	
379	    public Reservation checkIn(Long id) {
380	        Reservation reservation = reservationRepository.findById(id)
381	            .orElseThrow(() -> new ReservationNotFoundException());
382	
383	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
384	            throw new OperationNotAllowedException();
385	        }
386	
387	        reservation.setStatus(ReservationStatus.CHECKED_IN);
388	        return reservationRepository.save(reservation);
389	    }
390	
391	    public Reservation checkOut(Long id) {
392	        Reservation reservation = reservationRepository.findById(id)
393	            .orElseThrow(() -> new ReservationNotFoundException());
394	
395	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
396	            throw new OperationNotAllowedException();
397	        }
398	
399	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
400	        return reservationRepository.save(reservation);
401	    }
402	
403	    public String generateReceipt(Reservation reservation) {
404	        if (reservation.getStatus() == ReservationStatus.PENDING) {
405	            throw new OperationNotAllowedException();
406	        }
407	
408	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
409	            .orElseThrow(() -> new RoomNotFoundException());
410	
411	        StringBuilder receipt = new StringBuilder();
412	        receipt.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
413	        receipt.append(String.format("Hóspede: %s (CPF %s)\n",
414	            reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
415	        receipt.append(String.format("Quarto: %s (%s)\n",
416	            reservation.getRoomNumber(), room.getType().name()));
417	        receipt.append(String.format("Entrada: %s | Saída: %s | %d %s\n",
418	            formatDate(reservation.getCheckIn()),
419	            formatDate(reservation.getCheckOut()),
420	            reservation.getNights(),
421	            reservation.getNights() == 1 ? "diária" : "diárias"));
422	        receipt.append(String.format("Diárias: %s\n", formatMoney(reservation.getSubtotal())));
423	
424	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
425	            receipt.append(String.format("Desconto: %s\n", formatMoney(reservation.getDiscount())));
426	        }
427	
428	        receipt.append(String.format("Total: %s", formatMoney(reservation.getTotal())));
429	
430	        return receipt.toString();
431	    }
432	
433	    private String formatCpf(String cpf) {
434	        if (cpf.length() == 11) {
435	            return String.format("%s.%s.%s-%s",
436	                cpf.substring(0, 3),
437	                cpf.substring(3, 6),
438	                cpf.substring(6, 9),
439	                cpf.substring(9, 11));
440	        }
441	        return cpf;
442	    }
443	
444	    private String formatDate(LocalDate date) {
445	        return String.format("%02d/%02d/%04d",
446	            date.getDayOfMonth(),
447	            date.getMonthValue(),
448	            date.getYear());
449	    }
450	
451	    private String formatMoney(BigDecimal amount) {
452	        String formatted = String.format("%,.2f", amount);
453	        formatted = formatted.replace(',', 'X').replace('.', ',').replace('X', '.');
454	        return "R$ " + formatted;
455	    }
