175	        }
176	
177	        csv.append("total,").append(formatCsvNumber(totalTax));
178	
179	        return csv.toString();
180	    }
181	
182	    public String generateRatePlansReport(String month) {
183	        List<Reservation> reservations = reservationRepository.findByCheckInMonth(month);
184	
185	        List<Reservation> relevantReservations = reservations.stream()
186	            .filter(r -> r.getStatus() == ReservationStatus.CONFIRMED ||
187	                        r.getStatus() == ReservationStatus.CHECKED_IN ||
188	                        r.getStatus() == ReservationStatus.CHECKED_OUT ||
189	                        (r.getStatus() == ReservationStatus.CANCELLED &&
190	                         r.getRatePlan() == RatePlan.NON_REFUNDABLE))
191	            .toList();
192	
193	        Map<RatePlan, List<Reservation>> byPlan = relevantReservations.stream()
194	            .collect(Collectors.groupingBy(Reservation::getRatePlan));
195	
196	        StringBuilder csv = new StringBuilder();
197	        csv.append("Pousada Maré Alta,rate-plans,").append(month).append("\n");
198	        csv.append("rate_plan,reservations,amount\n");
199	
200	        BigDecimal totalAmount = BigDecimal.ZERO;
201	        int totalCount = 0;
202	
203	        for (RatePlan plan : RatePlan.values()) {
204	            List<Reservation> planReservations = byPlan.getOrDefault(plan, Collections.emptyList());
205	            int count = planReservations.size();
206	
207	            BigDecimal amount = planReservations.stream()
208	                .map(r -> {
209	                    BigDecimal net = r.getAmountPaid();
210	                    if (r.getRefund() != null) {
211	                        net = net.subtract(r.getRefund());
212	                    }
213	                    return net;
214	                })
215	                .reduce(BigDecimal.ZERO, BigDecimal::add);
216	
217	            csv.append(plan.name()).append(",");
218	            csv.append(count).append(",");
219	            csv.append(formatCsvNumber(amount)).append("\n");
220	
221	            totalAmount = totalAmount.add(amount);
222	            totalCount += count;
223	        }
224	
225	        csv.append("total,").append(totalCount).append(",").append(formatCsvNumber(totalAmount));
226	
227	        return csv.toString();
228	    }
229	
230	    private String formatCsvNumber(BigDecimal value) {
231	        return value.setScale(2, java.math.RoundingMode.HALF_EVEN).toPlainString();
232	    }
