245	public class ReservationService {
246	    private final ReservationRepository reservationRepository;
247	    private final RoomRepository roomRepository;
248	    private final MessageRepository messageRepository;
249	    private final PricingService pricingService;
250	
251	    public ReservationService(ReservationRepository reservationRepository,
252	                            RoomRepository roomRepository,
253	                            MessageRepository messageRepository,
254	                            PricingService pricingService) {
255	        this.reservationRepository = reservationRepository;
256	        this.roomRepository = roomRepository;
257	        this.messageRepository = messageRepository;
258	        this.pricingService = pricingService;
259	    }
260	
261	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
262	                                       String guestCpf, LocalDate checkIn, LocalDate checkOut,
263	                                       int guests, RatePlan ratePlan) {
264	        Room room = roomRepository.findByNumber(roomNumber)
265	            .orElseThrow(() -> new RoomNotFoundException());
266	
267	        if (guests < 1) {
268	            throw new InvalidRequestException("At least one guest is required");
269	        }
270	
271	        if (guests > room.getCapacity()) {
272	            throw new CapacityExceededException();
273	        }
274	
275	        if (!checkOut.isAfter(checkIn)) {
276	            throw new InvalidRequestException("Check-out must be after check-in");
277	        }
278	
279	        var conflicts = reservationRepository.findConflicting(roomNumber, checkIn, checkOut, null);
280	        if (!conflicts.isEmpty()) {
281	            throw new RoomUnavailableException();
282	        }
283	
284	        Reservation reservation = new Reservation();
285	        reservation.setRoomNumber(roomNumber);
286	        reservation.setGuestName(guestName);
287	        reservation.setGuestEmail(guestEmail);
288	        reservation.setGuestCpf(guestCpf);
289	        reservation.setCheckIn(checkIn);
290	        reservation.setCheckOut(checkOut);
291	        reservation.setGuests(guests);
292	        reservation.setRatePlan(ratePlan);
293	
294	        calculatePricing(reservation, room);
295	
296	        return reservationRepository.save(reservation);
297	    }
298	
299	    private void calculatePricing(Reservation reservation, Room room) {
300	        int nights = (int) ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
301	        reservation.setNights(nights);
302	
303	        BigDecimal subtotal = BigDecimal.ZERO;
304	        LocalDate currentDate = reservation.getCheckIn();
305	
306	        for (int i = 0; i < nights; i++) {
307	            BigDecimal nightPrice = pricingService.calculateNightPrice(room.getNightlyRate(), currentDate);
308	            subtotal = subtotal.add(nightPrice);
309	            currentDate = currentDate.plusDays(1);
310	        }
311	
312	        subtotal = pricingService.roundBankers(subtotal);
313	        reservation.setSubtotal(subtotal);
314	
315	        BigDecimal discount = BigDecimal.ZERO;
316	        if (reservation.getRatePlan() == RatePlan.NON_REFUNDABLE) {
317	            discount = pricingService.roundBankers(subtotal.multiply(reservation.getRatePlan().getDiscountRate()));
318	        }
319	        reservation.setDiscount(discount);
320	
321	        BigDecimal total = pricingService.roundBankers(subtotal.subtract(discount));
322	        reservation.setTotal(total);
323	    }
324	
325	    public Reservation confirmReservation(Long id) {
326	        Reservation reservation = reservationRepository.findById(id)
327	            .orElseThrow(() -> new ReservationNotFoundException());
328	
329	        if (reservation.getStatus() != ReservationStatus.PENDING) {
330	            throw new OperationNotAllowedException();
331	        }
332	
333	        reservation.setStatus(ReservationStatus.CONFIRMED);
334	        reservation.setAmountPaid(reservation.getTotal());
335	        reservationRepository.save(reservation);
336	
337	        sendConfirmationEmail(reservation);
338	
339	        return reservation;
340	    }
341	
342	    private void sendConfirmationEmail(Reservation reservation) {
343	        String receipt = generateReceipt(reservation);
344	        String subject = "Reserva confirmada - Pousada Maré Alta";
345	        String body = String.format("""
346	            Olá, %s!
347	
348	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
349	
350	            %s
351	
352	            A entrada é a partir das 14h, e a saída, até as 12h.
353	            Até breve!""", reservation.getGuestName(), receipt);
354	
355	        Message message = new Message(MessageChannel.EMAIL, reservation.getGuestEmail(), subject, body);
356	        messageRepository.save(message);
357	    }
358	
359	    public Reservation cancelReservation(Long id) {
360	        Reservation reservation = reservationRepository.findById(id)
361	            .orElseThrow(() -> new ReservationNotFoundException());
362	
363	        if (reservation.getStatus() != ReservationStatus.PENDING &&
364	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
365	            throw new OperationNotAllowedException();
366	        }
367	
368	        reservation.setStatus(ReservationStatus.CANCELLED);
369	
370	        BigDecimal refundAmount = BigDecimal.ZERO;
371	        if (reservation.getRatePlan() == RatePlan.STANDARD) {
372	            refundAmount = reservation.getAmountPaid();
373	        }
374	        reservation.setRefund(refundAmount);
375	
376	        return reservationRepository.save(reservation);
377	    }
378	
379	    public Reservation checkIn(Long id) {
380	        Reservation reservation = reservationRepository.findById(id)
381	            .orElseThrow(() -> new ReservationNotFoundException());
382	
383	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
384	            throw new OperationNotAllowedException();
385	        }
386	
387	        reservation.setStatus(ReservationStatus.CHECKED_IN);
388	        return reservationRepository.save(reservation);
389	    }
390	
391	    public Reservation checkOut(Long id) {
392	        Reservation reservation = reservationRepository.findById(id)
393	            .orElseThrow(() -> new ReservationNotFoundException());
394	
395	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
396	            throw new OperationNotAllowedException();
397	        }
398	
399	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
400	        return reservationRepository.save(reservation);
401	    }
402	
403	    public String generateReceipt(Reservation reservation) {
404	        if (reservation.getStatus() == ReservationStatus.PENDING) {
405	            throw new OperationNotAllowedException();
406	        }
407	
408	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
409	            .orElseThrow(() -> new RoomNotFoundException());
410	
411	        StringBuilder receipt = new StringBuilder();
412	        receipt.append(String.format("Comprovante de reserva nº %d\n", reservation.getId()));
413	        receipt.append(String.format("Hóspede: %s (CPF %s)\n",
414	            reservation.getGuestName(), formatCpf(reservation.getGuestCpf())));
415	        receipt.append(String.format("Quarto: %s (%s)\n",
416	            reservation.getRoomNumber(), room.getType().name()));
417	        receipt.append(String.format("Entrada: %s | Saída: %s | %d %s\n",
418	            formatDate(reservation.getCheckIn()),
419	            formatDate(reservation.getCheckOut()),
420	            reservation.getNights(),
421	            reservation.getNights() == 1 ? "diária" : "diárias"));
422	        receipt.append(String.format("Diárias: %s\n", formatMoney(reservation.getSubtotal())));
423	
424	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
425	            receipt.append(String.format("Desconto: %s\n", formatMoney(reservation.getDiscount())));
426	        }
427	
428	        receipt.append(String.format("Total: %s", formatMoney(reservation.getTotal())));
429	
430	        return receipt.toString();
431	    }
432	
433	    private String formatCpf(String cpf) {
434	        if (cpf.length() == 11) {
435	            return String.format("%s.%s.%s-%s",
436	                cpf.substring(0, 3),
437	                cpf.substring(3, 6),
438	                cpf.substring(6, 9),
439	                cpf.substring(9, 11));
440	        }
441	        return cpf;
442	    }
443	
444	    private String formatDate(LocalDate date) {
445	        return String.format("%02d/%02d/%04d",
446	            date.getDayOfMonth(),
447	            date.getMonthValue(),
448	            date.getYear());
449	    }
450	
451	    private String formatMoney(BigDecimal amount) {
452	        String formatted = String.format("%,.2f", amount);
453	        formatted = formatted.replace(',', 'X').replace('.', ',').replace('X', '.');
454	        return "R$ " + formatted;
455	    }
456	
457	    public static class RoomNotFoundException extends RuntimeException {
458	    }
459	
460	    public static class ReservationNotFoundException extends RuntimeException {
461	    }
462	
463	    public static class InvalidRequestException extends RuntimeException {
464	        public InvalidRequestException(String message) {
465	            super(message);
466	        }
467	    }
468	
469	    public static class CapacityExceededException extends RuntimeException {
470	    }
471	
472	    public static class RoomUnavailableException extends RuntimeException {
473	    }
474	
475	    public static class OperationNotAllowedException extends RuntimeException {
476	    }
477	}

