     9	import static org.assertj.core.api.Assertions.assertThat;
    10	
    11	class PricingServiceTest {
    12	
    13	    private final PricingService pricingService = new PricingService();
    14	
    15	    @Test
    16	    void testHighSeasonDetection() {
    17	        assertThat(pricingService.isHighSeason(LocalDate.of(2027, 12, 15))).isTrue();
    18	        assertThat(pricingService.isHighSeason(LocalDate.of(2027, 12, 31))).isTrue();
    19	        assertThat(pricingService.isHighSeason(LocalDate.of(2027, 1, 1))).isTrue();
    20	        assertThat(pricingService.isHighSeason(LocalDate.of(2027, 2, 28))).isTrue();
    21	        assertThat(pricingService.isHighSeason(LocalDate.of(2027, 7, 1))).isTrue();
    22	        assertThat(pricingService.isHighSeason(LocalDate.of(2027, 7, 31))).isTrue();
    23	
    24	        assertThat(pricingService.isHighSeason(LocalDate.of(2027, 12, 14))).isFalse();
    25	        assertThat(pricingService.isHighSeason(LocalDate.of(2027, 3, 1))).isFalse();
    26	        assertThat(pricingService.isHighSeason(LocalDate.of(2027, 6, 30))).isFalse();
    27	        assertThat(pricingService.isHighSeason(LocalDate.of(2027, 8, 1))).isFalse();
    28	    }
    29	
    30	    @Test
    31	    void testHighSeasonPricing() {
    32	        BigDecimal baseRate = new BigDecimal("249.90");
    33	        LocalDate highSeasonDate = LocalDate.of(2027, 7, 10);
    34	
    35	        BigDecimal price = pricingService.calculateNightPrice(baseRate, highSeasonDate);
    36	
    37	        assertThat(price).isEqualByComparingTo(new BigDecimal("299.88"));
    38	    }
    39	
    40	    @Test
    41	    void testBankersRounding() {
    42	        assertThat(pricingService.roundBankers(new BigDecimal("1.125"))).isEqualByComparingTo(new BigDecimal("1.12"));
    43	        assertThat(pricingService.roundBankers(new BigDecimal("1.135"))).isEqualByComparingTo(new BigDecimal("1.14"));
    44	        assertThat(pricingService.roundBankers(new BigDecimal("1.145"))).isEqualByComparingTo(new BigDecimal("1.14"));
    45	        assertThat(pricingService.roundBankers(new BigDecimal("1.155"))).isEqualByComparingTo(new BigDecimal("1.16"));
    46	    }
